import{readFileSync,writeFileSync,existsSync,unlinkSync,mkdirSync}from'node:fs';import{randomBytes,createHash}from'node:crypto';import{homedir}from'node:os';import{join}from'node:path';import{productionEnvironment,productionPsql,productionKeys,PRODUCTION_API_ORIGIN}from'../scripts/lib/production-database.mjs';import{practiceData,uuidFrom,capacityOwnersPassword,removeCapacityOwners}from'../scripts/lib/capacity-load.mjs';
const root=process.cwd(),mode=process.argv[2];if(!['seed','cleanup'].includes(mode))throw Error('seed|cleanup');const protocol=JSON.parse(readFileSync('.verification/targeted-performance-protocol-20261025.json'));if(protocol.runtimeSource!=='0851de59ed7971debe2514e6d6851d142bbc5766')throw Error('PROTOCOL');const stateFile='.verification/targeted-performance-fixture-20261025.json',secret=join(homedir(),'.config/cita-suite/production/targeted-perf-20261025-secret');const{env,database}=productionEnvironment(root);const{serviceKey}=productionKeys(env);const data=practiceData(1),owner=uuidFrom('capacity-owner-1');const admin=(path,init={})=>fetch(PRODUCTION_API_ORIGIN+'/auth/v1/admin'+path,{...init,headers:{authorization:'Bearer '+serviceKey,apikey:serviceKey,'content-type':'application/json'},signal:AbortSignal.timeout(20000)});const sql=(text,more={})=>productionPsql(database,text,{application:'cita_suite_targeted_fixture',timeout:180000,...more});
const counts=()=>JSON.parse(sql(`begin transaction read only;select jsonb_build_object('businesses',(select count(*)from public.businesses),'patients',(select count(*)from public.patients),'appointments',(select count(*)from public.appointments),'calendarConnections',(select count(*)from public.google_calendar_connections),'calendarEvents',(select count(*)from public.appointment_google_calendar_events),'storedObjects',(select count(*)from storage.objects),'storedObjectBytes',(select sum((metadata->>'size')::bigint)from storage.objects),'capacity',(select count(*)from public.businesses where slug like 'capacity-%'),'capacityOwners',(select count(*)from auth.users where email like 'capacity-owner-%@example.test'),'databaseBytes',pg_database_size(current_database()));commit;`));
if(mode==='seed'){
 if(existsSync(stateFile)||existsSync(secret))throw Error('EXISTING_FIXTURE_INSPECT');const before=counts();if(before.capacity||before.capacityOwners||before.databaseBytes+50000000>300000000)throw Error('BUDGET_OR_FIXTURE_NOT_EMPTY');const version=await(await fetch('https://app.cita-suite.workers.dev/_app/version.json')).json();if(version.version!==protocol.runtimeSource)throw Error('RUNTIME_CHANGED');mkdirSync(join(homedir(),'.config/cita-suite/production'),{recursive:true,mode:0o700});writeFileSync(secret,randomBytes(32).toString('base64url'),{flag:'wx',mode:0o600});const r={at:new Date().toISOString(),protocol:protocol.protocol,runtime:version.version,status:'secret-created',before,practices:1,ownerCreated:false,seedCompleted:false,secretRemoved:false,applicationCredentialsChanged:false};const save=()=>writeFileSync(stateFile,JSON.stringify(r,null,2)+'\n',{mode:0o600});save();const q=await admin('/users',{method:'POST',body:JSON.stringify({id:owner,email:data.email,password:capacityOwnersPassword(readFileSync(secret,'utf8'),'targeted-production'),email_confirm:true})});const user=await q.json();if(!q.ok||user.id!==owner)throw Error('OWN_AUTH_CREATE_FAILED');r.ownerCreated=true;r.status='owner-created';save();const source=readFileSync('scripts/capacity/seed-practices.sql','utf8');r.seedSqlSha256=createHash('sha256').update(source).digest('hex');const output=sql(source,{args:['-Atq','-v','practices=1','-v','owners='+JSON.stringify([owner])]});writeFileSync('.verification/targeted-performance-seed-20261025.log',output,{flag:'wx',mode:0o600});const line=output.split('\n').find(x=>x.startsWith('capacity-seed '));if(!line)throw Error('SEED_RESULT_MISSING');r.seed=JSON.parse(line.slice('capacity-seed '.length));if(r.seed.patients!==6000||r.seed.appointments!==12000||r.seed.practices!==1)throw Error('SEED_COUNT_MISMATCH');r.seedCompleted=true;r.status='seeded';r.after=counts();save();console.log({status:r.status,seed:r.seed,databaseBytes:r.after.databaseBytes});
}else{
 if(!existsSync(stateFile))throw Error('OWN_STATE_MISSING');const r=JSON.parse(readFileSync(stateFile));if(r.status==='cleaned')throw Error('ALREADY_CLEANED');if(!r.ownerCreated)throw Error('NO_OWN_OWNER');const source=readFileSync('scripts/capacity/cleanup-practices.sql','utf8');const output=sql(source);writeFileSync('.verification/targeted-performance-cleanup-20261025.log',output,{flag:'wx',mode:0o600});const line=output.split('\n').find(x=>x.startsWith('capacity-cleanup '));if(!line)throw Error('CLEANUP_RESULT_MISSING');r.removed=JSON.parse(line.slice('capacity-cleanup '.length));if(r.removed.practices!==1||r.removed.patients<6000||r.removed.appointments<12000)throw Error('CLEANUP_COUNT_MISMATCH');r.ownersRemoved=await removeCapacityOwners({practices:1,request:admin});r.afterCleanup=counts();for(const[k,v]of Object.entries(r.before))if(k!=='databaseBytes'&&r.afterCleanup[k]!==v)throw Error('PREEXISTING_COUNTS_CHANGED');if(r.ownersRemoved!==1)throw Error('OWN_OWNER_NOT_REMOVED');unlinkSync(secret);r.secretRemoved=true;r.status='cleaned';r.cleanedAt=new Date().toISOString();r.cleanupSqlSha256=createHash('sha256').update(source).digest('hex');writeFileSync(stateFile,JSON.stringify(r,null,2)+'\n',{mode:0o600});console.log({status:r.status,removed:r.removed,ownersRemoved:r.ownersRemoved,priorCountsRestored:true});
}
